import { useState, useEffect } from "react";
import FullCalendar from "@fullcalendar/react";
import dayGridPlugin from "@fullcalendar/daygrid";
import interactionPlugin from "@fullcalendar/interaction";
import axios from "axios";
import { Dialog } from "primereact/dialog";
import { Button } from "primereact/button";
import { InputText } from "primereact/inputtext";
import { Calendar } from "primereact/calendar";
import { Dropdown } from "primereact/dropdown";
import { User, Dog, ClipboardList } from "lucide-react"; // Icons
import "../components/css/VetDashboard.css";


const VetDashboard = () => {
  const clinicId = localStorage.getItem("clinicId");
  const role = localStorage.getItem("role");
  const [appointments, setAppointments] = useState([]);
  const [error, setError] = useState(null);
  const [selectedAppointments, setSelectedAppointments] = useState([]);
  const [isDialogVisible, setIsDialogVisible] = useState(false);
  const [isAddDialogVisible, setIsAddDialogVisible] = useState(false);
  const [owners, setOwners] = useState([]);
  const [pets, setPets] = useState([]);
  const [selectedOwnerId, setSelectedOwnerId] = useState(null);
  const [selectedPetId, setSelectedPetId] = useState(null);
  
  // Form State for Adding Appointment
  const [newAppointment, setNewAppointment] = useState({
    ownerName: "",
    petName: "",
    petType: "",
    services: "",
    date: null,
  });

  useEffect(() => {
    if (clinicId && role === "clinic") {
      fetchOwners();
    }

    fetchAppointments();
  }, [clinicId, role]);

  const fetchOwners = async () => {
    try {
      const response = await axios.get(`http://localhost:5000/api/appointments/owners/clinic/${clinicId}`);
      setOwners(response.data);
    } catch (error) {
      console.error("Error fetching owners:", error);
    }
  };

  // Fetch pets when an owner is selected
  useEffect(() => {
    const fetchPets = async () => {
      if (!selectedOwnerId) return;
      try {
        const response = await axios.get(`http://localhost:5000/api/pets/owner/${selectedOwnerId}`);
        setPets(response.data);
      } catch (error) {
        console.error("Error fetching pets:", error);
      }
    };

    fetchPets();
  }, [selectedOwnerId]);


  const fetchAppointments = async () => {
    try {
      let response;
      if (role === "admin") {
        response = await axios.get(`http://localhost:5000/api/appointments/`);
      } else if (role === "clinic" && clinicId) {
        response = await axios.get(`http://localhost:5000/api/appointments/clinics/${clinicId}`);
      } else {
        setError("Clinic ID is not available for this role.");
        return;
      }

      const filteredAppointments = response.data.filter(appt => {
        const status = appt.status ? appt.status.toLowerCase() : "";
        return status === "pending" || status === "confirmed";
      });

      setAppointments(filteredAppointments);
    } catch (error) {
      console.error("Error fetching appointments:", error);
      setError("Error fetching appointments. Please try again later.");
    }
  };

  // Group appointments by date
  const groupedAppointments = appointments.reduce((acc, apt) => {
    const date = apt.date.split("T")[0];
    if (!acc[date]) acc[date] = [];
    acc[date].push(apt);
    return acc;
  }, {});

  // Format data for FullCalendar
  const calendarEvents = Object.keys(groupedAppointments).map((date) => ({
    title: `${groupedAppointments[date].length} Appointments`,
    start: date,
    allDay: true,
    extendedProps: { details: groupedAppointments[date] },
  }));

  // Show details when clicking on an event
  const handleEventClick = (info) => {
    setSelectedAppointments(info.event.extendedProps.details);
    setIsDialogVisible(true);
  };

  // Handle adding new appointment
  const handleAddAppointment = async () => {
    if (!newAppointment.ownerName || !newAppointment.petName || !newAppointment.date) {
      alert("Please fill out all required fields.");
      return;
    }

    try {
      const response = await axios.post(`http://localhost:5000/api/appointments/`, {
        clinicId,
        ownerName: newAppointment.ownerName,
        pet: {
          name: newAppointment.petName,
          type: newAppointment.petType,
        },
        services: newAppointment.services ? newAppointment.services.split(",") : [],
        date: newAppointment.date.toISOString(),
        status: "pending",
      });

      setAppointments([...appointments, response.data]); // Update calendar
      setIsAddDialogVisible(false);
      setNewAppointment({ ownerName: "", petName: "", petType: "", services: "", date: null });
    } catch (error) {
      console.error("Error adding appointment:", error);
      alert("Error adding appointment. Please try again.");
    }
  };

  return (
    <div className="bg-white p-6 rounded-lg shadow-md">
      <h2 className="text-2xl font-bold mb-4">Appointment Schedule</h2>
      {error && <p className="text-red-500">{error}</p>}

      {/* Add Appointment Button (Only for Clinics) */}
      {role === "clinic" && (
        <Button label="Add Appointment" className="mb-4" onClick={() => setIsAddDialogVisible(true)} />
      )}

      <FullCalendar
        plugins={[dayGridPlugin, interactionPlugin]}
        initialView="dayGridMonth"
        events={calendarEvents}
        eventClick={handleEventClick}
        height="600px"
        eventContent={(eventInfo) => (
          <div style={{ cursor: "pointer" }}>
            {eventInfo.event.title}
          </div>
        )}
      />

      {/* Appointment Details Modal */}
      <Dialog
        header={<span className="text-lg font-semibold">Appointment Details</span>}
        visible={isDialogVisible}
        onHide={() => setIsDialogVisible(false)}
        className="p-4"
      >
        <div className="space-y-4">
          {selectedAppointments.map((apt, index) => (
            <div key={index} className="p-4 border rounded-lg shadow-sm bg-gray-100">
              <p className="flex items-center gap-2 text-lg font-medium">
                <User size={18} className="text-blue-500" /> {apt.ownerName || "Guest"}
              </p>
              <p className="flex items-center gap-2 text-gray-700">
                <Dog size={18} className="text-green-500" /> {apt.petDetails || "No Pets"}
              </p>
              <p className="flex items-center gap-2 text-gray-700">
                <ClipboardList size={18} className="text-purple-500" /> {apt.service_id?.name || "No Services Listed"}
              </p>
            </div>
          ))}
        </div>
      </Dialog>

      {/* Add Appointment Modal */}
      <Dialog
        header="Add-Appointment"
        visible={isAddDialogVisible}
        onHide={() => setIsAddDialogVisible(false)}
        className="p-4"
      >
        <div className="add-appointment">
          <InputText
            placeholder="Owner Name"
            value={newAppointment.ownerName}
            onChange={(e) => setNewAppointment({ ...newAppointment, ownerName: e.target.value })}
            className="w-full"
          />
          <InputText
            placeholder="Pet Name"
            value={newAppointment.petName}
            onChange={(e) => setNewAppointment({ ...newAppointment, petName: e.target.value })}
            className="w-full"
          />
          <InputText
            placeholder="Pet Type (e.g., Dog, Cat)"
            value={newAppointment.petType}
            onChange={(e) => setNewAppointment({ ...newAppointment, petType: e.target.value })}
            className="w-full"
          />
          <InputText
            placeholder="Services (comma-separated)"
            value={newAppointment.services}
            onChange={(e) => setNewAppointment({ ...newAppointment, services: e.target.value })}
            className="w-full"
          />
          <Calendar
            placeholder="Select Date"
            value={newAppointment.date}
            onChange={(e) => setNewAppointment({ ...newAppointment, date: e.value })}
            showIcon
            className="w-full"
          />
          <Button label="Add Appointment" className="w-full" onClick={handleAddAppointment} />
        </div>
      </Dialog>
    </div>
  );
};

export default VetDashboard;
